YUI.add('moodle-availability_siakadpaid-form',function(Y,NAME){M.availability_siakadpaid=M.availability_siakadpaid||{};M.availability_siakadpaid.form=Y.Object(M.core_availability.plugin);M.availability_siakadpaid.form.config={prodis:[],defaults:{}};M.availability_siakadpaid.form.initInner=function(c){this.config=c||{prodis:[],defaults:{}}};M.availability_siakadpaid.form.getNode=function(j){var c=this.config||{prodis:[],defaults:{}},d=c.defaults||{},h='<div class="availability-group d-flex flex-wrap gap-2 align-items-center"><label>'+M.util.get_string('label_prodi','availability_siakadpaid')+' <select name="prodi" class="form-select d-inline-block w-auto"><option value="choose">'+M.util.get_string('choose','availability_siakadpaid')+'</option><option value="*">'+M.util.get_string('anyprodi','availability_siakadpaid')+'</option>';for(var i=0;i<(c.prodis||[]).length;i++){h+='<option value="'+Y.Escape.html(c.prodis[i].code)+'">'+Y.Escape.html(c.prodis[i].name)+'</option>'}h+='</select></label><label>'+M.util.get_string('label_tahunajaran','availability_siakadpaid')+' <input class="form-control d-inline-block w-auto" type="text" name="tahunajaran"></label><label>'+M.util.get_string('label_semester','availability_siakadpaid')+' <select class="form-select d-inline-block w-auto" name="semester"><option value="">-</option><option value="ganjil">'+M.util.get_string('semester_ganjil','availability_siakadpaid')+'</option><option value="genap">'+M.util.get_string('semester_genap','availability_siakadpaid')+'</option></select></label><label>'+M.util.get_string('label_jenis','availability_siakadpaid')+' <input class="form-control d-inline-block w-auto" type="text" name="jenis" placeholder="'+M.util.get_string('allbilltypes','availability_siakadpaid')+'"></label></div>';var n=Y.Node.create('<span class="availability_siakadpaid">'+h+'</span>');n.one('[name=prodi]').set('value',j.prodi||'choose');n.one('[name=tahunajaran]').set('value',j.tahunajaran!==undefined?j.tahunajaran:(d.tahunajaran||''));n.one('[name=semester]').set('value',j.semester!==undefined?j.semester:(d.semester||''));n.one('[name=jenis]').set('value',j.jenis||'');n.all('select,input').on('change',function(){M.core_availability.form.update()});return n};M.availability_siakadpaid.form.fillValue=function(v,n){v.prodi=n.one('[name=prodi]').get('value');v.tahunajaran=n.one('[name=tahunajaran]').get('value').trim();v.semester=n.one('[name=semester]').get('value');v.jenis=n.one('[name=jenis]').get('value').trim()};M.availability_siakadpaid.form.fillErrors=function(e,n){var v={};this.fillValue(v,n);if(!v.prodi||v.prodi==='choose'){e.push('availability_siakadpaid:error_selectprodi')}}},'@VERSION@',{"requires":["base","node","event","escape","moodle-core_availability-form"]});
